css:
.loader {
  position: relative;
  width: 34px;
  height: 50px;
  animation: float 1.8s ease-in-out infinite;
}
.loader::before {
  content: "";
  position: absolute;
  top: 0;
  left: 50%;
  width: 30px;
  height: 34px;
  margin-left: -15px;
  border-radius: 50% 50% 46% 46%;
  background: #6366f1;
}
.loader i {
  position: absolute;
  top: 37px;
  left: 50%;
  width: 12px;
  height: 9px;
  margin-left: -6px;
  border-radius: 0 0 3px 3px;
  background: #4338ca;
}
.loader i::before {
  content: "";
  position: absolute;
  top: -6px;
  left: 1px;
  width: 1px;
  height: 6px;
  background: #4338ca;
  box-shadow: 8px 0 0 #4338ca;
}
@keyframes float {
  0%, 100% { transform: translateY(3px) rotate(-4deg); }
  50% { transform: translateY(-5px) rotate(4deg); }
}
